#include "ble_sensor.h"

#include <BLEDevice.h>
#include <BLEServer.h>
#include <BLEUtils.h>
#include <BLE2902.h>
#include <BLESecurity.h>
#include <Arduino.h>

#include "hx711_sensor.h"
#include "dht_sensor.h"
#include "ina226_sensor.h"
#include "max17043_sensor.h"

#define SERVICE_UUID        "12345678-1234-1234-1234-123456789012"
#define CHARACTERISTIC_UUID "abcd1234-ab12-ab12-ab12-abcdef123456"
#define DEVICE_NAME         "CEMO-IOT"
#define CLIENT_TIMEOUT_MS   5000     // 5s no notify ack = client gone

// ═══════════════════════════════════════════════════════════════════════════
// REALTIME OPTIMIZATION: Much faster update intervals for sensor data
// ═══════════════════════════════════════════════════════════════════════════

#define SENSOR_UPDATE_MS    50        // Update BLE every 50ms (20 Hz) for real-time feel
#define ENV_UPDATE_MS       500       // Update DHT/INA every 500ms (too slow to read faster)
#define BATTERY_UPDATE_MS   1000      // Update battery every 1000ms
#define BLE_NOTIFY_MIN_MS   50        // Throttle notifications if client is slow

static BLECharacteristic* pSensorChar     = nullptr;
static bool               deviceConnected = false;
static unsigned long      lastNotifyMs    = 0;
static unsigned long      lastActivityMs  = 0;
static unsigned long      lastEnvReadMs   = 0;
static unsigned long      lastBatteryMs   = 0;

// ═══════════════════════════════════════════════════════════════════════════
// Data cache for fast updates (read sensors slowly, send data fast)
// ═══════════════════════════════════════════════════════════════════════════

static struct {
    float weight = 0.0f;
    float temp   = 0.0f;
    float hum    = 0.0f;
    float volt   = 0.0f;
    float curr   = 0.0f;
    float soc    = 0.0f;
} sensorCache;

// ───────────────────────── SECURITY ─────────────────────────

class CemoSecurityCallbacks : public BLESecurityCallbacks {
    bool onConfirmPIN(uint32_t pin) override {
        return true;
    }

    uint32_t onPassKeyRequest() override {
        return 0;
    }

    void onPassKeyNotify(uint32_t pass_key) override {}

    bool onSecurityRequest() override {
        return true;
    }
};

// ───────────────────────── SERVER CALLBACKS ─────────────────────────

class CemoServerCallbacks : public BLEServerCallbacks {
    void onConnect(BLEServer* pServer) override {
        deviceConnected = true;
        lastActivityMs  = millis();  // reset watchdog on connect
        BLEDevice::setMTU(185);
        Serial.println("[BLE] Connected");
    }

    void onDisconnect(BLEServer* pServer) override {
        deviceConnected = false;
        lastActivityMs  = 0;         // clear watchdog on disconnect
        Serial.println("[BLE] Disconnected → restarting advertising");
        BLEDevice::startAdvertising();
    }
};

// ───────────────────────── INIT ─────────────────────────

void ble_init() {
    BLEDevice::init(DEVICE_NAME);
    BLEDevice::setMTU(185);

    // Security (triggers Android pairing popup — Android drives bond)
    BLEDevice::setSecurityCallbacks(new CemoSecurityCallbacks());

    BLESecurity* security = new BLESecurity();

    security->setAuthenticationMode(
        ESP_LE_AUTH_REQ_SC_BOND
    );

    security->setCapability(ESP_IO_CAP_NONE);

    security->setInitEncryptionKey(
        ESP_BLE_ENC_KEY_MASK | ESP_BLE_ID_KEY_MASK
    );

    security->setRespEncryptionKey(
        ESP_BLE_ENC_KEY_MASK | ESP_BLE_ID_KEY_MASK
    );

    // Server
    BLEServer* server = BLEDevice::createServer();
    server->setCallbacks(new CemoServerCallbacks());

    BLEService* service = server->createService(SERVICE_UUID);

    pSensorChar = service->createCharacteristic(
        CHARACTERISTIC_UUID,
        BLECharacteristic::PROPERTY_NOTIFY
    );

    pSensorChar->addDescriptor(new BLE2902());

    service->start();

    // Advertising
    BLEAdvertising* adv = BLEDevice::getAdvertising();
    adv->addServiceUuid(SERVICE_UUID);
    adv->setScanResponse(true);
    adv->setMinPreferred(0x06);

    BLEDevice::startAdvertising();

    Serial.println("[BLE] Advertising started");
}

// ───────────────────────── REALTIME UPDATE LOOP ─────────────────────────

void ble_update() {
    // Watchdog — if connected but no successful notify for 5s,
    // the Android client is likely gone (BT turned off abruptly).
    // Force a disconnect and restart advertising.
    if (deviceConnected && lastActivityMs > 0 &&
        (millis() - lastActivityMs > CLIENT_TIMEOUT_MS)) {
        Serial.println("[BLE] Client timeout — forcing disconnect");
        deviceConnected = false;
        lastActivityMs  = 0;
        BLEDevice::startAdvertising();
        return;
    }

    if (!deviceConnected) return;

    // ─────────────────────────────────────────────────────────────
    // SLOW SENSOR READS (500-1000ms intervals) — cached locally
    // ─────────────────────────────────────────────────────────────

    unsigned long now = millis();

    if (now - lastEnvReadMs >= ENV_UPDATE_MS) {
        lastEnvReadMs = now;

        // Read slow sensors only when needed
        sensorCache.weight = scaleConnected ? (readWeightSafe() / 1000.0f) : 0.0f;
        sensorCache.temp   = dhtOK ? sensorData.temperature : 0.0f;
        sensorCache.hum    = dhtOK ? sensorData.humidity : 0.0f;
        sensorCache.volt   = inaConnected ? loadVoltage_V : 0.0f;
        sensorCache.curr   = inaConnected ? ina226_getDisplayCurrent() : 0.0f;
    }

    if (now - lastBatteryMs >= BATTERY_UPDATE_MS) {
        lastBatteryMs = now;

        // Battery update only every 1s
        max17043_read();
        sensorCache.soc = max17043Connected ? max17043_getSoc() : 0.0f;
    }

    // ─────────────────────────────────────────────────────────────
    // FAST BLE NOTIFY (50ms intervals) — use cached values
    // ─────────────────────────────────────────────────────────────

    if (now - lastNotifyMs < SENSOR_UPDATE_MS) return;
    lastNotifyMs = now;

    // Build payload from cache (no sensor reads here)
    char payload[100];
    snprintf(payload, sizeof(payload),
        "WEIGHT:%.2f,TEMP:%.1f,HUM:%.1f,VOLT:%.2f,CURR:%.3f,SOC:%.1f",
        sensorCache.weight, sensorCache.temp, sensorCache.hum,
        sensorCache.volt, sensorCache.curr, sensorCache.soc
    );

    pSensorChar->setValue((uint8_t*)payload, strlen(payload));
    pSensorChar->notify();

    // Stamp activity after each successful notify
    lastActivityMs = millis();

    Serial.println(payload);
}

// ───────────────────────── STATUS ─────────────────────────

bool ble_isConnected() {
    return deviceConnected;
}

